[CmdletBinding()]
param(
    [string]$RepoRoot = "C:\Users\ChadDillerud\Documents\DocSync-Zetadocs"
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$ExpectedProductionVersion = "0.26.0.6"
$ExpectedTestVersion = "0.7.1.8"
$NewProductionVersion = "0.27.0.0"
$NewTestVersion = "0.8.0.0"

$BuildScript = Join-Path $RepoRoot "scripts\Prepare-GPIALTests.ps1"
$ProductionRoot = Join-Path $RepoRoot "bc-extension\zetadocs-replacement"
$TestRoot = Join-Path $RepoRoot "bc-extension\zetadocs-replacement-tests"

if (-not (Test-Path -LiteralPath $BuildScript)) {
    throw "Build script was not found: $BuildScript"
}

$Files = @(
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\src\codeunit\GPIRecordDocumentMgt.Codeunit.al'
        ExpectedHash = 'C21CEC25FA629F9A7DE93C4DDC4010E1CC6F6F5BAFC581B203F4BB652B08237D'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\src\page\GPIRecordDocumentsFactBox.Page.al'
        ExpectedHash = '1295882F0FA0AC2049D9E9313E0BBA74C9152228B317970BBD7F4097E37E7BEC'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\src\pageextension\GPISalesOrderRecordDocuments.PageExt.al'
        ExpectedHash = '4F0C70D6CC937D61F003537DD1BCBF601B1B6E345ECD4A9DCB2CE6CCEE384BB9'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\src\pageextension\GPIPurchaseOrderRecordDocuments.PageExt.al'
        ExpectedHash = 'B3F2F06E05FEEDDAC4A055876D1AA07FB1EB332568E05F7D102AB99F78186170'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\src\permissionset\GPIRecordDocuments.PermissionSet.al'
        ExpectedHash = '12BAB6E10B619515CEE0E3395670D926E6B5800118FC4C2F6FFB3BD45ADD732D'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement-tests\src\codeunit\GPIDeliveryLogTests.Codeunit.al'
        ExpectedHash = '1AB5342A345FEBA85E864EC509A10EA2DF30C061B62D6A982D7D51E5A6B8DA07'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\app.json'
        ExpectedHash = 'ACE2AAFDA151C7705E592D8BC780AB10A3931BD2265473E970AB9F36BC72B985'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement-tests\app.json'
        ExpectedHash = '6E9DD6FD3F330C530BFF5C0CF1F4E529DEE920176F3F89E8C20B3DCA9DCB1DCF'
        ContentBase64 = ''
    },
    [pscustomobject]@{
        RelativePath = 'bc-extension\zetadocs-replacement\CHANGELOG.md'
        ExpectedHash = '9386F7D02B576EBCBDE071AEC5A4456C10087463636E5F55352F20F79DBB2FC1'
        ContentBase64 = ''
    }
)

function Write-Utf8NoBom {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Content
    )

    $Encoding = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Content, $Encoding)
}

function Get-Sha256 {
    param([Parameter(Mandatory)][string]$Path)

    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
}

$ProductionAppJson = Join-Path $ProductionRoot "app.json"
$TestAppJson = Join-Path $TestRoot "app.json"

$ProductionApp = Get-Content -LiteralPath $ProductionAppJson -Raw | ConvertFrom-Json
$TestApp = Get-Content -LiteralPath $TestAppJson -Raw | ConvertFrom-Json

if ([string]$ProductionApp.version -ne $ExpectedProductionVersion) {
    throw "Expected production version $ExpectedProductionVersion, but found $($ProductionApp.version). No files were changed."
}

if ([string]$TestApp.version -ne $ExpectedTestVersion) {
    throw "Expected test version $ExpectedTestVersion, but found $($TestApp.version). No files were changed."
}

foreach ($File in $Files) {
    $FullPath = Join-Path $RepoRoot $File.RelativePath

    if (-not (Test-Path -LiteralPath $FullPath)) {
        throw "Required source file was not found: $FullPath"
    }

    $ActualHash = Get-Sha256 -Path $FullPath
    if ($ActualHash -ne $File.ExpectedHash) {
        throw "Source file changed after the Gamer Documents capture: $($File.RelativePath). Expected SHA256 $($File.ExpectedHash), found $ActualHash. No files were changed."
    }
}

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $RepoRoot ".gpi-backups\gamer-documents-unified-history-$Timestamp"
New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

foreach ($File in $Files) {
    $FullPath = Join-Path $RepoRoot $File.RelativePath
    $BackupPath = Join-Path $BackupRoot $File.RelativePath
    New-Item -ItemType Directory -Path (Split-Path -Parent $BackupPath) -Force | Out-Null
    Copy-Item -LiteralPath $FullPath -Destination $BackupPath -Force
}

$ProductionPackage = Join-Path $ProductionRoot "Gamer Packaging_GPI Sales Document Email_$NewProductionVersion.app"
$TestPackage = Join-Path $TestRoot "Gamer Packaging_GPI Sales Document Email Tests_$NewTestVersion.app"

try {
    foreach ($File in $Files) {
        $FullPath = Join-Path $RepoRoot $File.RelativePath
        $ContentBytes = [Convert]::FromBase64String($File.ContentBase64)
        $Content = [Text.Encoding]::UTF8.GetString($ContentBytes)
        Write-Utf8NoBom -Path $FullPath -Content $Content
    }

    if (Test-Path -LiteralPath $ProductionPackage) {
        Remove-Item -LiteralPath $ProductionPackage -Force
    }

    if (Test-Path -LiteralPath $TestPackage) {
        Remove-Item -LiteralPath $TestPackage -Force
    }

    $BuildStdOut = Join-Path $BackupRoot "build.stdout.log"
    $BuildStdErr = Join-Path $BackupRoot "build.stderr.log"

    $BuildProcess = Start-Process `
        -FilePath "powershell.exe" `
        -ArgumentList @(
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            ('"' + $BuildScript + '"')
        ) `
        -Wait `
        -PassThru `
        -RedirectStandardOutput $BuildStdOut `
        -RedirectStandardError $BuildStdErr

    $StdOutText = if (Test-Path -LiteralPath $BuildStdOut) {
        Get-Content -LiteralPath $BuildStdOut -Raw
    }
    else {
        ""
    }

    $StdErrText = if (Test-Path -LiteralPath $BuildStdErr) {
        Get-Content -LiteralPath $BuildStdErr -Raw
    }
    else {
        ""
    }

    if (-not [string]::IsNullOrWhiteSpace($StdOutText)) {
        Write-Host $StdOutText
    }

    if (-not [string]::IsNullOrWhiteSpace($StdErrText)) {
        Write-Host $StdErrText
    }

    if ($BuildProcess.ExitCode -ne 0) {
        throw "The production or test extension build failed with exit code $($BuildProcess.ExitCode)."
    }

    if (-not (Test-Path -LiteralPath $ProductionPackage)) {
        throw "The expected production package was not created: $ProductionPackage"
    }

    if (-not (Test-Path -LiteralPath $TestPackage)) {
        throw "The expected test package was not created: $TestPackage"
    }
}
catch {
    Write-Host ""
    Write-Host "The Gamer Documents build failed. Restoring all modified files." -ForegroundColor Red

    foreach ($File in $Files) {
        $FullPath = Join-Path $RepoRoot $File.RelativePath
        $BackupPath = Join-Path $BackupRoot $File.RelativePath
        Copy-Item -LiteralPath $BackupPath -Destination $FullPath -Force
    }

    if (Test-Path -LiteralPath $ProductionPackage) {
        Remove-Item -LiteralPath $ProductionPackage -Force
    }

    if (Test-Path -LiteralPath $TestPackage) {
        Remove-Item -LiteralPath $TestPackage -Force
    }

    throw
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host " Gamer Documents unified history build passed" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "Production version: $NewProductionVersion"
Write-Host "Test version:       $NewTestVersion"
Write-Host "Production package: $ProductionPackage"
Write-Host "Test package:       $TestPackage"
Write-Host "Backup:             $BackupRoot"
Write-Host ""
Write-Host "Implemented:" -ForegroundColor Cyan
Write-Host "  - Sales Order and Purchase Order FactBoxes renamed to Gamer Documents"
Write-Host "  - Successfully sent PDFs merged with manually uploaded files"
Write-Host "  - Sent documents open from SharePoint when archived"
Write-Host "  - Sent documents download the exact retained PDF before or after archive failure"
Write-Host "  - Drafts, previews, discarded messages, and failed sends excluded"
Write-Host "  - Repeat sends retained as separate history entries"
Write-Host ""
Write-Host "No package was published." -ForegroundColor Yellow
Write-Host "Publish both packages only to Sandbox_5_5_2026, refresh the VS Code Testing panel, and run the complete test suite." -ForegroundColor Yellow
